// test-full-migrations.ts
//
// Script completo de validação:
// 1. Cria banco limpo
// 2. Executa todas as migrations
// 3. Valida estrutura
// 4. Inicia servidor e testa rotas

import dotenv from 'dotenv';
import { join } from 'path';
import { Pool } from 'pg';
import { readdir, readFile, writeFile } from 'fs/promises';
import { buildApp } from './src/server';

// Carrega variáveis de ambiente
dotenv.config({ path: join(process.cwd(), '.env') });

const TEST_DB_NAME = process.env.TEST_DB_NAME || 'unificard_test';
const DATABASE_URL = process.env.DATABASE_URL || '';
const MIGRATIONS_DIR = join(process.cwd(), 'migrations');

interface TestResult {
  success: boolean;
  message: string;
  details?: any;
}

class MigrationTester {
  private adminPool: Pool;
  private testPool: Pool | null = null;
  private logs: string[] = [];

  constructor() {
    // Conecta ao banco postgres para criar/dropar banco de teste
    const urlParts = new URL(DATABASE_URL);
    const adminUrl = `postgresql://${urlParts.username}:${urlParts.password}@${urlParts.hostname}:${urlParts.port || 5432}/postgres`;
    
    this.adminPool = new Pool({ connectionString: adminUrl });
  }

  log(message: string, ...args: any[]) {
    const timestamp = new Date().toISOString();
    const logMessage = `[${timestamp}] ${message} ${args.length > 0 ? JSON.stringify(args) : ''}`;
    console.log(logMessage);
    this.logs.push(logMessage);
  }

  async dropDatabaseIfExists(): Promise<void> {
    this.log('🗑️  Tentando dropar banco de teste se existir...');
    
    try {
      const client = await this.adminPool.connect();
      try {
        // Termina conexões existentes
        await client.query(`
          SELECT pg_terminate_backend(pg_stat_activity.pid)
          FROM pg_stat_activity
          WHERE pg_stat_activity.datname = $1
            AND pid <> pg_backend_pid();
        `, [TEST_DB_NAME]);

        await client.query(`DROP DATABASE IF EXISTS ${TEST_DB_NAME};`);
        this.log('✅ Banco de teste dropado com sucesso');
      } finally {
        client.release();
      }
    } catch (error) {
      // Se o banco não existe, não é erro
      if (error instanceof Error && error.message.includes('does not exist')) {
        this.log('ℹ️  Banco de teste não existe, continuando...');
      } else {
        this.log('⚠️  Erro ao dropar banco (pode não existir):', error);
      }
    }
  }

  async createDatabase(): Promise<void> {
    this.log('📦 Criando banco de teste...');
    
    try {
      const client = await this.adminPool.connect();
      try {
        await client.query(`CREATE DATABASE ${TEST_DB_NAME};`);
        this.log('✅ Banco de teste criado com sucesso');
      } finally {
        client.release();
      }
    } catch (error) {
      throw new Error(`Erro ao criar banco: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  async getMigrationFiles(): Promise<string[]> {
    const files = await readdir(MIGRATIONS_DIR);
    return files
      .filter((file) => file.endsWith('.sql'))
      .sort((a, b) => a.localeCompare(b));
  }

  async runMigrations(): Promise<TestResult> {
    this.log('🚀 Iniciando execução de migrations...\n');

    try {
      const migrationFiles = await this.getMigrationFiles();
      this.log(`📋 Encontradas ${migrationFiles.length} migration(s) para executar:\n`);
      migrationFiles.forEach((file, index) => {
        this.log(`  ${index + 1}. ${file}`);
      });
      this.log('');

      const testPool = this.getTestPool();

      // Testa conexão
      const testClient = await testPool.connect();
      try {
        await testClient.query('SELECT 1');
        this.log('✔ Conexão com banco de teste estabelecida\n');
      } finally {
        testClient.release();
      }

      // Executa cada migration
      for (let i = 0; i < migrationFiles.length; i++) {
        const filename = migrationFiles[i];
        const migrationPath = join(MIGRATIONS_DIR, filename);
        
        this.log(`[${i + 1}/${migrationFiles.length}] 📦 Executando migração: ${filename}`);
        
        const sql = await readFile(migrationPath, 'utf-8');
        
        if (!sql.trim()) {
          this.log(`⚠️  Arquivo vazio, pulando: ${filename}`);
          continue;
        }

        const client = await testPool.connect();
        try {
          await client.query(sql);
          this.log(`✅ Migração concluída: ${filename}\n`);
        } catch (error) {
          this.log(`❌ Erro ao executar migração ${filename}:`);
          this.log(error instanceof Error ? error.message : String(error));
          throw new Error(
            `Falha na migração ${filename}: ${error instanceof Error ? error.message : String(error)}`
          );
        } finally {
          client.release();
        }
      }

      this.log('✨ Todas as migrations foram aplicadas com sucesso!\n');

      // Verifica se todas as migrations foram executadas
      this.log(`📋 Verificando estrutura do banco...`);

      const verifyClient = await testPool.connect();
      try {
        // Verifica algumas tabelas essenciais
        const essentialTables = [
          'users',
          'tenants',
          'roles',
          'permissions',
          'groups',
          'social_posts',
          'instant_requests',
          'global_users',
        ];

        const missingTables: string[] = [];
        for (const table of essentialTables) {
          const result = await verifyClient.query(`
            SELECT EXISTS (
              SELECT FROM information_schema.tables 
              WHERE table_schema = 'public' 
              AND table_name = $1
            );
          `, [table]);

          if (!result.rows[0].exists) {
            missingTables.push(table);
          } else {
            this.log(`  ✓ Tabela ${table} existe`);
          }
        }

        if (missingTables.length > 0) {
          return {
            success: false,
            message: `Tabelas essenciais faltando: ${missingTables.join(', ')}`,
            details: { missingTables },
          };
        }

        this.log('✅ Todas as tabelas essenciais foram criadas');
      } finally {
        verifyClient.release();
      }

      return {
        success: true,
        message: `Todas as ${migrationFiles.length} migrations foram executadas com sucesso`,
        details: { migrationCount: migrationFiles.length, migrations: migrationFiles },
      };
    } catch (error) {
      return {
        success: false,
        message: `Erro ao executar migrations: ${error instanceof Error ? error.message : String(error)}`,
        details: { error },
      };
    }
  }

  getTestPool(): Pool {
    if (!this.testPool) {
      const urlParts = new URL(DATABASE_URL);
      const testDbUrl = `postgresql://${urlParts.username}:${urlParts.password}@${urlParts.hostname}:${urlParts.port || 5432}/${TEST_DB_NAME}`;
      this.testPool = new Pool({ connectionString: testDbUrl });
    }
    return this.testPool;
  }

  async testServerStartup(): Promise<TestResult> {
    this.log('\n🚀 Testando inicialização do servidor...');

    try {
      // Garante que DATABASE_URL está usando banco de teste
      const urlParts = new URL(DATABASE_URL);
      const testDbUrl = `postgresql://${urlParts.username}:${urlParts.password}@${urlParts.hostname}:${urlParts.port || 5432}/${TEST_DB_NAME}`;
      process.env.DATABASE_URL = testDbUrl;

      const app = await buildApp();
      
      // Apenas valida que o app foi construído sem erros
      // Não vamos iniciar o servidor aqui, apenas testar a build
      this.log('✅ Servidor construído com sucesso (sem erros de inicialização)');

      // Fecha o app
      await app.close();

      return {
        success: true,
        message: 'Servidor inicializou sem erros',
      };
    } catch (error) {
      return {
        success: false,
        message: `Erro ao inicializar servidor: ${error instanceof Error ? error.message : String(error)}`,
        details: { error },
      };
    }
  }

  async testRoutes(): Promise<TestResult> {
    this.log('\n🧪 Testando rotas críticas...');

    try {
      const urlParts = new URL(DATABASE_URL);
      const testDbUrl = `postgresql://${urlParts.username}:${urlParts.password}@${urlParts.hostname}:${urlParts.port || 5432}/${TEST_DB_NAME}`;
      process.env.DATABASE_URL = testDbUrl;

      const app = await buildApp();
      const testResults: Record<string, { success: boolean; status?: number; error?: string }> = {};

      try {
        // Teste 1: GET /metrics (pública)
        try {
          const response = await app.inject({
            method: 'GET',
            url: '/metrics',
          });
          testResults['/metrics'] = {
            success: response.statusCode === 200,
            status: response.statusCode,
          };
          this.log(`  ${response.statusCode === 200 ? '✅' : '❌'} GET /metrics - Status: ${response.statusCode}`);
        } catch (error) {
          testResults['/metrics'] = {
            success: false,
            error: error instanceof Error ? error.message : String(error),
          };
          this.log(`  ❌ GET /metrics - Erro: ${error instanceof Error ? error.message : String(error)}`);
        }

        // Teste 2: GET /groups (protegida - esperamos 401/403)
        try {
          const response = await app.inject({
            method: 'GET',
            url: '/groups',
          });
          testResults['/groups'] = {
            success: response.statusCode === 401 || response.statusCode === 403,
            status: response.statusCode,
          };
          this.log(`  ${response.statusCode === 401 || response.statusCode === 403 ? '✅' : '⚠️'} GET /groups - Status: ${response.statusCode} (esperado 401/403 sem auth)`);
        } catch (error) {
          testResults['/groups'] = {
            success: false,
            error: error instanceof Error ? error.message : String(error),
          };
          this.log(`  ❌ GET /groups - Erro: ${error instanceof Error ? error.message : String(error)}`);
        }

        // Teste 3: GET /social/feed (protegida - esperamos 401/403)
        try {
          const response = await app.inject({
            method: 'GET',
            url: '/social/feed',
          });
          testResults['/social/feed'] = {
            success: response.statusCode === 401 || response.statusCode === 403,
            status: response.statusCode,
          };
          this.log(`  ${response.statusCode === 401 || response.statusCode === 403 ? '✅' : '⚠️'} GET /social/feed - Status: ${response.statusCode} (esperado 401/403 sem auth)`);
        } catch (error) {
          testResults['/social/feed'] = {
            success: false,
            error: error instanceof Error ? error.message : String(error),
          };
          this.log(`  ❌ GET /social/feed - Erro: ${error instanceof Error ? error.message : String(error)}`);
        }

        // Teste 4: GET /work-instant/status/test (pode não existir, esperamos 404, 401 ou 403)
        try {
          const response = await app.inject({
            method: 'GET',
            url: '/work-instant/status/test',
          });
          testResults['/work-instant/status/test'] = {
            success: [401, 403, 404].includes(response.statusCode),
            status: response.statusCode,
          };
          this.log(`  ${[401, 403, 404].includes(response.statusCode) ? '✅' : '⚠️'} GET /work-instant/status/test - Status: ${response.statusCode}`);
        } catch (error) {
          testResults['/work-instant/status/test'] = {
            success: false,
            error: error instanceof Error ? error.message : String(error),
          };
          this.log(`  ❌ GET /work-instant/status/test - Erro: ${error instanceof Error ? error.message : String(error)}`);
        }

        // Teste 5: GET /health (pública)
        try {
          const response = await app.inject({
            method: 'GET',
            url: '/health',
          });
          testResults['/health'] = {
            success: response.statusCode === 200,
            status: response.statusCode,
          };
          this.log(`  ${response.statusCode === 200 ? '✅' : '❌'} GET /health - Status: ${response.statusCode}`);
        } catch (error) {
          testResults['/health'] = {
            success: false,
            error: error instanceof Error ? error.message : String(error),
          };
          this.log(`  ❌ GET /health - Erro: ${error instanceof Error ? error.message : String(error)}`);
        }

      } finally {
        await app.close();
        this.log('🛑 Servidor encerrado');
      }

      const allSuccess = Object.values(testResults).every(r => r.success);
      return {
        success: allSuccess,
        message: `Testes de rotas concluídos: ${Object.keys(testResults).filter(k => testResults[k].success).length}/${Object.keys(testResults).length} passaram`,
        details: testResults,
      };
    } catch (error) {
      return {
        success: false,
        message: `Erro ao testar rotas: ${error instanceof Error ? error.message : String(error)}`,
        details: { error },
      };
    }
  }

  async cleanup(): Promise<void> {
    if (this.testPool) {
      await this.testPool.end();
    }
    await this.adminPool.end();
  }

  getLogs(): string[] {
    return this.logs;
  }
}

// Função principal
async function main() {
  console.log('╔══════════════════════════════════════════════════════════╗');
  console.log('║   VALIDAÇÃO COMPLETA DE MIGRATIONS E INICIALIZAÇÃO      ║');
  console.log('╚══════════════════════════════════════════════════════════╝\n');

  if (!DATABASE_URL) {
    console.error('❌ Erro: DATABASE_URL não está configurada no .env');
    process.exit(1);
  }

  const tester = new MigrationTester();
  const results: TestResult[] = [];

  try {
    // 1. Preparar banco limpo
    await tester.dropDatabaseIfExists();
    await tester.createDatabase();

    // 2. Executar migrations
    const migrationResult = await tester.runMigrations();
    results.push(migrationResult);

    if (!migrationResult.success) {
      console.error('\n❌ Migrations falharam. Parando testes.\n');
      console.error(migrationResult.message);
      if (migrationResult.details) {
        console.error('Detalhes:', JSON.stringify(migrationResult.details, null, 2));
      }
      process.exit(1);
    }

    // 3. Testar inicialização do servidor
    const serverResult = await tester.testServerStartup();
    results.push(serverResult);

    if (!serverResult.success) {
      console.error('\n❌ Inicialização do servidor falhou.\n');
      console.error(serverResult.message);
      if (serverResult.details) {
        console.error('Detalhes:', JSON.stringify(serverResult.details, null, 2));
      }
      process.exit(1);
    }

    // 4. Testar rotas
    const routesResult = await tester.testRoutes();
    results.push(routesResult);

    // 5. Relatório final
    console.log('\n╔══════════════════════════════════════════════════════════╗');
    console.log('║                    RELATÓRIO FINAL                       ║');
    console.log('╚══════════════════════════════════════════════════════════╝\n');

    results.forEach((result, index) => {
      const labels = ['Migrations', 'Inicialização do Servidor', 'Testes de Rotas'];
      console.log(`${result.success ? '✅' : '❌'} ${labels[index]}: ${result.message}`);
    });

    const allSuccess = results.every(r => r.success);
    
    if (allSuccess) {
      console.log('\n✨ Todos os testes passaram com sucesso!');
    } else {
      console.log('\n❌ Alguns testes falharam. Verifique os logs acima.');
    }

    // Salva logs completos em arquivo
    const logContent = tester.getLogs().join('\n');
    const logFile = join(process.cwd(), 'migration-test-results.log');
    await writeFile(logFile, logContent, 'utf-8');
    console.log(`\n📝 Logs completos salvos em: ${logFile}`);

    if (!allSuccess) {
      process.exit(1);
    }

  } catch (error) {
    console.error('\n💥 Erro fatal:', error);
    
    // Salva logs mesmo em caso de erro
    try {
      const logContent = tester.getLogs().join('\n');
      const logFile = join(process.cwd(), 'migration-test-results.log');
      await writeFile(logFile, logContent + '\n\n💥 Erro fatal:\n' + (error instanceof Error ? error.stack : String(error)), 'utf-8');
      console.log(`\n📝 Logs salvos em: ${logFile}`);
    } catch (writeError) {
      // Ignora erro ao salvar logs
    }
    
    process.exit(1);
  } finally {
    await tester.cleanup();
  }
}

// Executa
main().catch((error) => {
  console.error('Erro não tratado:', error);
  process.exit(1);
});











